/// Cameras whose own DNGs get the matrices above instead of their tags.
const DNG_REPLACED: &[(&str, &str)] = &[("SAMSUNG TECHWIN Co.", "SAMSUNG GX20")];

/// Adobe's A and D65 matrices for a camera whose rawler entry is incomplete
/// or wrong, keyed by rawler's make and model strings.
pub fn corrected_color_matrix(
    make: &str,
    model: &str,
) -> Option<HashMap<Illuminant, FlatColorMatrix>> {
    CORRECTIONS
        .iter()
        .find(|(m, n, _, _)| *m == make.trim_end() && *n == model.trim_end())
        .map(|(_, _, a, d65)| {
            HashMap::from([(Illuminant::A, a.to_vec()), (Illuminant::D65, d65.to_vec())])
        })
}

/// Whether the camera's DNG colour tags are replaced by `CORRECTIONS`:
/// unusable in-camera tags, and Pixel DNGs without a gain table map.
pub fn replaces_dng_matrices(make: &str, model: &str, has_gain_table_map: bool) -> bool {
    // DNG Make/Model tags may be padded with spaces.
    let (make, model) = (make.trim_end(), model.trim_end());
    DNG_REPLACED.iter().any(|(m, n)| *m == make && *n == model)
        || (!has_gain_table_map
            && make == "Google"
            && CORRECTIONS
                .iter()
                .any(|(m, n, _, _)| *m == make && *n == model))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sony_a7_iv_gets_adobe_matrices() {
        let matrices = corrected_color_matrix("SONY", "ILCE-7M4").unwrap();
        assert_eq!(matrices[&Illuminant::D65][0], 0.7460);
        assert_eq!(matrices[&Illuminant::A][0], 0.8784);
        assert!(corrected_color_matrix("SONY", "ILCE-7M3").is_none());
    }

    #[test]
    fn replaced_dng_cameras_have_matrices() {
        for (make, model) in DNG_REPLACED {
            assert!(
                corrected_color_matrix(make, model).is_some(),
                "{make} {model}"
            );
        }
        assert!(!replaces_dng_matrices("SONY", "ILCE-7M4", false));
        assert!(replaces_dng_matrices("Google", "Pixel 6 Pro", false));
        assert!(!replaces_dng_matrices("Google", "Pixel 8 Pro", true));
        assert!(!replaces_dng_matrices("Google", "Pixel 3a", false));
    }

    #[test]
    fn corrections_are_unique_and_invertible() {
        for (i, (make, model, a, d65)) in CORRECTIONS.iter().enumerate() {
            assert!(
                CORRECTIONS[..i]
                    .iter()
                    .all(|(m, n, _, _)| (m, n) != (make, model)),
                "{make} {model} listed twice"
            );
            for m in [a, d65] {
                let det = m[0] * (m[4] * m[8] - m[5] * m[7]) - m[1] * (m[3] * m[8] - m[5] * m[6])
                    + m[2] * (m[3] * m[7] - m[4] * m[6]);
                assert!(det.abs() > 1e-3, "{make} {model}");
            }
        }
    }
}
